import { Injectable } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { Asignacion } from '../entities/asignacion.entity';
import { Producto } from '../../productos/entities/producto.entity';
import { Panadero } from '../../panaderos/entities/panadero.entity';

@Injectable()
export class AsignarPanaderoRepository {
  constructor(
    @InjectRepository(Asignacion) private readonly asignaciones: Repository<Asignacion>,
    @InjectRepository(Producto) private readonly productos: Repository<Producto>,
    @InjectRepository(Panadero) private readonly panaderos: Repository<Panadero>
  ) {}

  buscarProductoRepository(productoId: number) {
    return this.productos.findOneBy({ id: productoId });
  }

  buscarPanaderoRepository(panaderoId: number) {
    return this.panaderos.findOneBy({ id: panaderoId });
  }

  async asignarPanaderoRepository(productoId: number, panaderoId: number, rol: string) {
    const asignacion = { productoId, panaderoId, rol };
    await this.asignaciones.insert(asignacion);
    return asignacion;
  }
}

import { ConflictException, Injectable, NotFoundException } from '@nestjs/common';
import { QueryFailedError } from 'typeorm';
import { AsignarPanaderoRepository } from './repository';

@Injectable()
export class AsignarPanaderoService {
  constructor(private readonly repository: AsignarPanaderoRepository) {}

  async asignarPanaderoService(productoId: number, panaderoId: number, rol: string) {
    const producto = await this.repository.buscarProductoRepository(productoId);
    const panadero = await this.repository.buscarPanaderoRepository(panaderoId);
    if (!producto || !panadero) {
      throw new NotFoundException('No existe el producto o el panadero');
    }

    try {
      return await this.repository.asignarPanaderoRepository(productoId, panaderoId, rol);
    } catch (error) {
      if (error instanceof QueryFailedError && error.driverError.code === '23505') {
        throw new ConflictException('El panadero ya está asignado a ese producto');
      }
      throw error;
    }
  }
}

